import fs from "node:fs";
import path from "node:path";

const ROOT = process.cwd();
const REVISION = "v4-5-headphone-continuity-r1";
const BACKUP_SUFFIX = ".pre-studio-v4-5-headphone-continuity.bak";
const CORE = {"dsp/studio/mvp_studio_dsp.cpp": "", "public/audio/mvpStudioEngine.wasm": "", "src/lib/audio/mvpStudioEngine.ts": "", "src/lib/audio/mvpStudioDsp.worklet.js": "", "scripts/build-mvp-studio-wasm.sh": ""};

function fail(message) {
  console.error(`MVP Studio V4.5 installer stopped: ${message}`);
  console.error("Nothing was committed.");
  process.exit(1);
}
function read(rel) {
  const full=path.join(ROOT,rel);
  if(!fs.existsSync(full)) fail(`required file not found: ${rel}`);
  return fs.readFileSync(full,"utf8");
}
function replaceOnce(text, from, to, label) {
  const count=text.split(from).length-1;
  if(count!==1) fail(`${label} expected once but matched ${count}`);
  return text.replace(from,to);
}
function replaceSection(text,start,end,replacement,label){
  const s=text.indexOf(start); if(s<0) fail(`${label} start anchor not found`);
  const e=text.indexOf(end,s+start.length); if(e<0) fail(`${label} end anchor not found`);
  if(text.indexOf(start,s+1)>=0) fail(`${label} start anchor matched more than once`);
  return text.slice(0,s)+replacement+text.slice(e);
}

const rels={
  music:"src/lib/musicPlayer.ts",
  page:"src/features/music/MusicPage.tsx",
  workout:"src/features/workout/WorkoutPlayerPage.tsx",
};
let music=read(rels.music);
let page=read(rels.page);
let workout=read(rels.workout);

if(music.includes("MVP_STUDIO_V4_5_HEADPHONE_CONTINUITY") && workout.includes("mvp_active_cursor_session_id")) {
  console.log("MVP Studio V4.5 Headphone + Continuity is already installed."); process.exit(0);
}

// Baseline guards for the stable queue/workout APIs.
for(const anchor of ["export const MUSIC_HEADPHONE_MODES:","async function resolveSavedQueue","export function replaceMusicLibrary","export function activateMusicAdHocQueue","export function activateMusicPlaylistQueue"]) if(!music.includes(anchor)) fail(`music baseline anchor missing: ${anchor}`);
if(!page.includes('loadMusicLibrary(true)')) fail("MusicPage load baseline not found");
if(!page.includes('songSort === "recently_added"')) fail("Recently Added baseline not found");
if(!workout.includes('localStorage.setItem("mvp_active_exercise_pos"')) fail("workout cursor baseline not found");
if(!workout.includes('setItems(loaded);\n    setActiveIdx(0);') && !workout.includes('setItems(loaded);\r\n    setActiveIdx(0);')) fail("workout hydrate baseline not found");
const nl=music.includes("\r\n")?"\r\n":"\n";

// 1) Stronger, clearly differentiated headphone modes.
const hpBlock=`export const MUSIC_HEADPHONE_MODES: Record<\n  MusicHeadphoneMode,\n  { label: string; width: number; depth: number; crossfeed: number; center: number; bass: number }\n> = {\n  off: { label: "Off", width: 0, depth: 0, crossfeed: 0, center: 50, bass: 0 },\n  wide: { label: "Wide", width: 100, depth: 8, crossfeed: 2, center: 48, bass: 4 },\n  spatial: { label: "Spatial", width: 92, depth: 95, crossfeed: 18, center: 54, bass: 6 },\n  stage: { label: "Stage", width: 58, depth: 82, crossfeed: 62, center: 72, bass: 8 },\n  focus: { label: "Focus", width: 0, depth: 0, crossfeed: 30, center: 100, bass: 0 },\n  bass_impact: { label: "Bass Impact", width: 46, depth: 16, crossfeed: 8, center: 60, bass: 90 },\n};\n// MVP_STUDIO_V4_5_HEADPHONE_CONTINUITY\n`;
music=replaceSection(music,"export const MUSIC_HEADPHONE_MODES:","export const MUSIC_OUTPUT_PROFILES:",hpBlock+"export const MUSIC_OUTPUT_PROFILES:","headphone modes");

// 2) Persist exact ad-hoc queue ordering (Recently Added, filters, etc.).
music=replaceOnce(music,'  activePlaylistName: "mvp_music_active_playlist_name",','  activePlaylistName: "mvp_music_active_playlist_name",'+nl+'  activeQueueTrackIds: "mvp_music_active_queue_track_ids_v1",',"queue storage key");

const resolver=`async function resolveSavedQueue(libraryTracks: MusicTrack[]) {\n  const savedPlaylistId = readStored(STORAGE_KEYS.activePlaylistId);\n  if (!savedPlaylistId) {\n    const savedQueueName = readStored(STORAGE_KEYS.activePlaylistName);\n    const savedQueueIdsRaw = readStored(STORAGE_KEYS.activeQueueTrackIds);\n    if (savedQueueName && savedQueueIdsRaw) {\n      try {\n        const ids = JSON.parse(savedQueueIdsRaw);\n        if (Array.isArray(ids) && ids.length) {\n          const byId = new Map(libraryTracks.map((track) => [track.id, track]));\n          const tracks = ids.map((id) => byId.get(String(id))).filter((track): track is MusicTrack => Boolean(track));\n          if (tracks.length) return { tracks, playlistId: null as string | null, playlistName: savedQueueName };\n        }\n      } catch { /* fall through */ }\n    }\n    removePlayerSetting(STORAGE_KEYS.activePlaylistName);\n    removePlayerSetting(STORAGE_KEYS.activeQueueTrackIds);\n    return { tracks: libraryTracks, playlistId: null as string | null, playlistName: null as string | null };\n  }\n  try {\n    const [playlist, links] = await Promise.all([getMusicPlaylist(savedPlaylistId), listMusicPlaylistTrackLinks(savedPlaylistId)]);\n    if (!playlist) throw new Error("Playlist no longer exists.");\n    const byId = new Map(libraryTracks.map((track) => [track.id, track]));\n    const tracks = links.map((link) => byId.get(link.track_id)).filter((track): track is MusicTrack => Boolean(track));\n    if (!tracks.length) throw new Error("Playlist is empty.");\n    return { tracks, playlistId: playlist.id, playlistName: playlist.name };\n  } catch {\n    removePlayerSetting(STORAGE_KEYS.activePlaylistId);\n    removePlayerSetting(STORAGE_KEYS.activePlaylistName);\n    removePlayerSetting(STORAGE_KEYS.activeQueueTrackIds);\n    return { tracks: libraryTracks, playlistId: null as string | null, playlistName: null as string | null };\n  }\n}\n`;
music=replaceSection(music,"async function resolveSavedQueue(libraryTracks: MusicTrack[]) {","export async function loadMusicLibrary",resolver+"export async function loadMusicLibrary","saved queue resolver");

const replaceLib=`export function replaceMusicLibrary(libraryTracks: MusicTrack[]) {\n  const byId = new Map(libraryTracks.map((track) => [track.id, track]));\n  const hasScopedQueue = Boolean(state.activePlaylistId || state.activePlaylistName);\n  const tracks = hasScopedQueue\n    ? state.tracks.map((track) => byId.get(track.id) ?? track)\n    : libraryTracks;\n  const currentTrack = state.currentTrack\n    ? tracks.find((track) => track.id === state.currentTrack?.id) ?? byId.get(state.currentTrack.id) ?? state.currentTrack\n    : tracks[0] ?? null;\n  emit({ libraryTracks, tracks, currentTrack, libraryLoaded: true });\n  configureMediaSession();\n}\n`;
music=replaceSection(music,"export function replaceMusicLibrary(libraryTracks: MusicTrack[]) {","export function activateAllMusicTracks()",replaceLib+"export function activateAllMusicTracks()","replaceMusicLibrary");
music=replaceOnce(music,'  removePlayerSetting(STORAGE_KEYS.activePlaylistName);'+nl+'  const currentTrack =','  removePlayerSetting(STORAGE_KEYS.activePlaylistName);'+nl+'  removePlayerSetting(STORAGE_KEYS.activeQueueTrackIds);'+nl+'  const currentTrack =',"activate all queue cleanup");

const adhoc=`export function activateMusicAdHocQueue(name: string, tracks: MusicTrack[]) {\n  removePlayerSetting(STORAGE_KEYS.activePlaylistId);\n  savePlayerSetting(STORAGE_KEYS.activePlaylistName, name);\n  savePlayerSetting(STORAGE_KEYS.activeQueueTrackIds, JSON.stringify(tracks.map((track) => track.id)));\n  const currentTrack = tracks.find((track) => track.id === state.currentTrack?.id) ?? tracks[0] ?? null;\n  emit({ tracks: [...tracks], currentTrack, activePlaylistId: null, activePlaylistName: name, error: tracks.length ? null : "This collection has no songs." });\n  configureMediaSession();\n}\n`;
music=replaceSection(music,"export function activateMusicAdHocQueue(name: string, tracks: MusicTrack[]) {","export async function playMusicAdHocQueue",adhoc+"export async function playMusicAdHocQueue","ad-hoc queue");

const playlist=`export function activateMusicPlaylistQueue(\n  playlist: Pick<MusicPlaylist, "id" | "name">,\n  tracks: MusicTrack[],\n) {\n  savePlayerSetting(STORAGE_KEYS.activePlaylistId, playlist.id);\n  savePlayerSetting(STORAGE_KEYS.activePlaylistName, playlist.name);\n  removePlayerSetting(STORAGE_KEYS.activeQueueTrackIds);\n  const currentTrack = tracks.find((track) => track.id === state.currentTrack?.id) ?? tracks[0] ?? null;\n  emit({ tracks: [...tracks], currentTrack, activePlaylistId: playlist.id, activePlaylistName: playlist.name, error: tracks.length ? null : "This playlist has no songs." });\n  configureMediaSession();\n}\n`;
music=replaceSection(music,"export function activateMusicPlaylistQueue(","export async function playMusicPlaylist",playlist+"export async function playMusicPlaylist","playlist queue");

// 3) Music page mount should not force-rehydrate the singleton audio engine.
page=replaceOnce(page,"Promise.all([refreshTracks(), refreshPlaylists(), loadMusicLibrary(true)])","Promise.all([refreshTracks(), refreshPlaylists(), loadMusicLibrary()])","MusicPage mount continuity");

// 4) Persist exact workout exercise cursor.
const cursorAnchor='      localStorage.setItem("mvp_active_exercise_pos", pos ? `(${pos})` : "");';
const cursorInsert=cursorAnchor+nl+'      if (sessionId && workoutId && current) {'+nl+'        localStorage.setItem("mvp_active_cursor_session_id", String(sessionId));'+nl+'        localStorage.setItem("mvp_active_cursor_workout_id", String(workoutId));'+nl+'        localStorage.setItem("mvp_active_exercise_index", String(activeIdx));'+nl+'        if (current.id) localStorage.setItem("mvp_active_workout_exercise_row_id", String(current.id));'+nl+'        if (current.exercise_id) localStorage.setItem("mvp_active_exercise_id", String(current.exercise_id));'+nl+'      }';
workout=replaceOnce(workout,cursorAnchor,cursorInsert,"workout cursor persistence");

const hydrateOld='    setItems(loaded);'+nl+'    setActiveIdx(0);';
const hydrateNew=`    let restoredActiveIdx = 0;\n    try {\n      const cursorSession = localStorage.getItem("mvp_active_cursor_session_id");\n      const cursorWorkout = localStorage.getItem("mvp_active_cursor_workout_id");\n      if (cursorSession === String(sessionId) && cursorWorkout === String(wId)) {\n        const rowId = localStorage.getItem("mvp_active_workout_exercise_row_id");\n        const exerciseId = localStorage.getItem("mvp_active_exercise_id");\n        const savedIndex = Number(localStorage.getItem("mvp_active_exercise_index"));\n        const rowIndex = rowId ? loaded.findIndex((row) => String(row.id) === rowId) : -1;\n        const exerciseIndex = exerciseId ? loaded.findIndex((row) => String(row.exercise_id) === exerciseId) : -1;\n        if (rowIndex >= 0) restoredActiveIdx = rowIndex;\n        else if (exerciseIndex >= 0) restoredActiveIdx = exerciseIndex;\n        else if (Number.isInteger(savedIndex) && savedIndex >= 0 && savedIndex < loaded.length) restoredActiveIdx = savedIndex;\n      }\n    } catch { /* local cursor is optional */ }\n    setItems(loaded);\n    setActiveIdx(restoredActiveIdx);`;
workout=replaceOnce(workout,hydrateOld,hydrateNew,"workout cursor restore");

// Validate all patches before any write.
for(const [name,text,markers] of [
  ["musicPlayer",music,["MVP_STUDIO_V4_5_HEADPHONE_CONTINUITY","activeQueueTrackIds","width: 100","bass: 90"]],
  ["MusicPage",page,["loadMusicLibrary()"]],
  ["WorkoutPlayer",workout,["mvp_active_cursor_session_id","restoredActiveIdx"]],
]) for(const marker of markers) if(!text.includes(marker)) fail(`${name} post-patch validation missing ${marker}`);

const textUpdates=new Map([[rels.music,music],[rels.page,page],[rels.workout,workout]]);
const coreDecoded=new Map(Object.entries(CORE).map(([rel,b64])=>[rel,Buffer.from(b64,"base64")]));

// Stage all outputs first.
const staged=[];
try {
  for(const [rel,text] of textUpdates){ const full=path.join(ROOT,rel), tmp=full+".v45tmp"; fs.writeFileSync(tmp,text,"utf8"); staged.push([full,tmp]); }
  for(const [rel,bytes] of coreDecoded){ const full=path.join(ROOT,rel); if(!fs.existsSync(full)) fail(`core destination missing: ${rel}`); const tmp=full+".v45tmp"; fs.writeFileSync(tmp,bytes); staged.push([full,tmp]); }
  for(const [full] of staged) fs.copyFileSync(full,full+BACKUP_SUFFIX);
  for(const [full,tmp] of staged) fs.renameSync(tmp,full);
} catch(error){ for(const [,tmp] of staged){try{if(fs.existsSync(tmp))fs.unlinkSync(tmp)}catch{}} fail(error instanceof Error?error.message:String(error)); }

console.log("MVP Studio V4.5 Headphone + Continuity applied successfully.");
console.log(`(${REVISION})`);
console.log("Headphones: stronger immersion + adaptive final output drive before true-peak limiting.");
console.log("Recently Added: exact newest-to-older queue order persists from the selected song.");
console.log("Music navigation: active queue/current track are preserved instead of force-rehydrated.");
console.log("Workout Resume: exact last exercise is restored for the active session/workout.");
console.log(`Backups: *${BACKUP_SUFFIX}`);
console.log("NEXT: run npm run build");
